const { fonte, janela } = $json;
const versaoApi = 'v1';
const locationId = String(fonte.externalId).split('locations/').pop();
const MAXIMO_DE_MESES = 3;
const comDimensoes = fonte?.comDimensoes !== false;
const metricas = [
  'BUSINESS_IMPRESSIONS_DESKTOP_MAPS', 'BUSINESS_IMPRESSIONS_DESKTOP_SEARCH', 'BUSINESS_IMPRESSIONS_MOBILE_MAPS', 'BUSINESS_IMPRESSIONS_MOBILE_SEARCH',
  'BUSINESS_DIRECTION_REQUESTS', 'CALL_CLICKS', 'WEBSITE_CLICKS', 'MESSAGING_CLICKS', 'BUSINESS_BOOKINGS', 'BUSINESS_FOOD_MENU_CLICKS',
];
const [anoInicio, mesInicio, diaInicio] = janela.start.split('-').map(Number);
const [anoFim, mesFim, diaFim] = janela.end.split('-').map(Number);
const parametrosDiarios = [
  `dailyRange.start_date.year=${anoInicio}`, `dailyRange.start_date.month=${mesInicio}`, `dailyRange.start_date.day=${diaInicio}`,
  `dailyRange.end_date.year=${anoFim}`, `dailyRange.end_date.month=${mesFim}`, `dailyRange.end_date.day=${diaFim}`,
  ...metricas.map((metrica) => `dailyMetrics=${metrica}`),
].join('&');

const meses = [];
for (let ano = anoInicio, mes = mesInicio; ano < anoFim || (ano === anoFim && mes <= mesFim); mes += 1) {
  if (mes > 12) { mes = 1; ano += 1; }
  meses.push({ ano, mes });
}

const desempenho = `https://businessprofileperformance.googleapis.com/${versaoApi}/locations/${locationId}`;
const requisicoes = [
  { rotulo: 'diario', url: `${desempenho}:fetchMultiDailyMetricsTimeSeries?${parametrosDiarios}` },
  ...(comDimensoes ? meses.slice(-MAXIMO_DE_MESES) : []).map(({ ano, mes }) => ({
    rotulo: 'palavras_chave',
    mes: `${String(ano).padStart(4, '0')}-${String(mes).padStart(2, '0')}-01`,
    url: `${desempenho}/searchkeywords/impressions/monthly?monthlyRange.start_month.year=${ano}&monthlyRange.start_month.month=${mes}&monthlyRange.end_month.year=${ano}&monthlyRange.end_month.month=${mes}&pageSize=100`,
  })),
  ...(comDimensoes ? [{
    rotulo: 'local',
    url: `https://mybusinessbusinessinformation.googleapis.com/${versaoApi}/locations/${locationId}?readMask=${encodeURIComponent('name,title,categories,storefrontAddress,openInfo,websiteUri')}`,
  }] : []),
];

const inicio = Date.now();
return requisicoes.map((requisicao) => ({ json: { inicio, versaoApi, fonte, ...requisicao } }));

const requisicoes = $('Montar requisição').all().map((item) => item.json);
const respostas = $input.all().map((item) => item.json);
const contexto = requisicoes[0];
const todas = respostas.map((resposta, indice) => ({ requisicao: requisicoes[indice], resposta }));
const requests = todas.length;
const bytes = todas.reduce((total, { resposta }) => total + JSON.stringify(resposta?.body ?? {}).length, 0);

function devolver(linhas, falhas) {
  return [{
    json: {
      linhas,
      volumetria: { linhas: linhas.length, bytes, requests, duracaoMs: Date.now() - contexto.inicio },
      falhas,
      requests,
      versaoApi: contexto.versaoApi,
    },
  }];
}

const CONFIGURACAO_DO_PROJETO = /SERVICE_DISABLED|accessNotConfigured|has not been used in project/;
const SINAIS_DE_LIMITE = /RESOURCE_EXHAUSTED|RATE_LIMIT|rateLimitExceeded|userRateLimitExceeded|quotaExceeded|dailyLimitExceeded|Quota exceeded|Exhausted|Too many requests/i;
const SINAIS_DE_COTA_DIARIA = /dailyLimitExceeded|quotaExceeded|per day|PerDay|daily|Number of operations/i;
function falhaDaRecusa(statusCode, erro, detalhe) {
  const texto = JSON.stringify(erro ?? {});
  if (CONFIGURACAO_DO_PROJETO.test(texto)) return { causa: 'api_recusou', detalhe };
  if (statusCode === 429 || SINAIS_DE_LIMITE.test(texto)) {
    return { causa: 'limite_de_uso', detalhe: (SINAIS_DE_COTA_DIARIA.test(texto) ? `cota_diaria: ${detalhe}` : detalhe).slice(0, 500) };
  }
  if (statusCode === 401 || statusCode === 403) return { causa: 'reauth_pending', detalhe };
  return { causa: 'api_recusou', detalhe };
}


const respostaOk = (resposta) => !resposta?.error && resposta?.statusCode >= 200 && resposta?.statusCode < 300;
const essencial = todas.find(({ requisicao }) => requisicao?.rotulo === 'diario');

if (essencial?.resposta?.error) {
  const detalhe = essencial.resposta.error?.message ?? String(essencial.resposta.error);
  return devolver([], [{ causa: 'api_recusou', detalhe: `falha de rede: ${detalhe}`.slice(0, 500) }]);
}

if (essencial && !respostaOk(essencial.resposta)) {
  const recusada = essencial.resposta;
  const erro = Array.isArray(recusada.body) ? recusada.body[0]?.error : recusada.body?.error;
  const detalhe = String(erro?.message || `HTTP ${recusada.statusCode}`).slice(0, 500);
  return devolver([], [falhaDaRecusa(recusada.statusCode, erro, detalhe)]);
}

const motivoDaRecusa = (resposta) => {
  if (resposta?.error) return `falha de rede: ${resposta.error?.message ?? String(resposta.error)}`;
  const erro = Array.isArray(resposta?.body) ? resposta.body[0]?.error : resposta?.body?.error;
  return String(erro?.message || `HTTP ${resposta?.statusCode}`);
};

function coletaIncompleta(recusas) {
  const porTabela = new Map();
  for (const { tabela, resposta } of recusas) {
    const atual = porTabela.get(tabela) ?? { total: 0, motivo: motivoDaRecusa(resposta) };
    porTabela.set(tabela, { ...atual, total: atual.total + 1 });
  }
  return [...porTabela].map(([tabela, { total, motivo }]) => ({
    causa: 'coleta_incompleta',
    detalhe: `${tabela}: ${total > 1 ? `${total} pedidos recusados, ` : ''}${motivo}`.slice(0, 500),
  }));
}

const pad = (valor, tamanho) => String(valor ?? 0).padStart(tamanho, '0');
const inteiroOuNulo = (valor) => (valor == null || valor === '' ? null : Number(valor));

const tradutores = {
  diario: ({ resposta }) => {
    const linhas = [];
    for (const serie of resposta.body?.multiDailyMetricTimeSeries ?? []) {
      for (const metricaSerie of serie?.dailyMetricTimeSeries ?? []) {
        for (const valorDatado of metricaSerie?.timeSeries?.datedValues ?? []) {
          const data = valorDatado?.date ?? {};
          linhas.push({
            metricDate: `${pad(data.year, 4)}-${pad(data.month, 2)}-${pad(data.day, 2)}`,
            metric: metricaSerie?.dailyMetric ?? '',
            value: Number(valorDatado?.value ?? 0),
          });
        }
      }
    }
    return linhas;
  },
  palavras_chave: ({ requisicao, resposta }) => (resposta.body?.searchKeywordsCounts ?? [])
    .filter((entrada) => entrada?.searchKeyword)
    .map((entrada) => ({
      _tabela: 'palavras_chave',
      mes: requisicao.mes,
      termo: entrada.searchKeyword,
      valor: inteiroOuNulo(entrada.insightsValue?.value),
      limiar: inteiroOuNulo(entrada.insightsValue?.threshold),
    })),
  local: ({ resposta }) => {
    const local = resposta.body ?? {};
    if (!local.name && !local.title) return [];
    const endereco = local.storefrontAddress ?? {};
    return [{
      _tabela: 'dim_local',
      nome: local.title ?? null,
      categoriaPrimaria: local.categories?.primaryCategory?.displayName ?? null,
      endereco: (endereco.addressLines ?? []).join(', ') || null,
      cidade: endereco.locality ?? null,
      estado: endereco.administrativeArea ?? null,
      cep: endereco.postalCode ?? null,
      pais: endereco.regionCode ?? null,
      status: local.openInfo?.status ?? null,
      site: local.websiteUri ?? null,
    }];
  },
};

const linhas = todas
  .filter(({ requisicao, resposta }) => requisicao && tradutores[requisicao.rotulo] && respostaOk(resposta))
  .flatMap((entrada) => tradutores[entrada.requisicao.rotulo](entrada));

const TABELA_DO_ROTULO = { 'local': 'dim_local' };

const incompletas = coletaIncompleta(todas
  .filter(({ requisicao, resposta }) => requisicao && tradutores[requisicao.rotulo] && requisicao.rotulo !== 'diario' && !respostaOk(resposta))
  .map(({ requisicao, resposta }) => ({ tabela: TABELA_DO_ROTULO[requisicao.rotulo] ?? requisicao.rotulo, resposta })));

if (linhas.length === 0) return devolver([], incompletas.length > 0 ? incompletas : [{ causa: 'sem_dados_no_periodo', detalhe: null }]);
return devolver(linhas.map((linha) => ({ ...linha, versaoApi: contexto.versaoApi })), incompletas);
